from random import randint, seed
import pandas as pd

# Method
def task_func(goals, penalties, rng_seed=None):
    """
    Build a DataFrame describing football match results for multiple teams.

    Parameters
    ----------
    goals : int | sequence
        Either a single goal value, a sequence of goal values, or a sequence of
        (low, high) tuples to be randomly sampled.
    penalties : int | sequence
        Either a single penalty value, a sequence of penalty values, or a
        sequence of (low, high) tuples to be randomly sampled.
    rng_seed : int | None
        Seed for reproducible random sampling when ranges are provided.

    Returns
    -------
    pd.DataFrame
        DataFrame with columns ['Team', 'Match Result'].
    """
    if rng_seed is not None:
        seed(rng_seed)

    PENALTY_COST = 100

    def _is_range_like(value):
        return (
            isinstance(value, (list, tuple))
            and len(value) == 2
            and all(isinstance(x, int) for x in value)
        )

    def _resolve(value):
        if _is_range_like(value):
            low, high = value
            if low > high:
                low, high = high, low
            return randint(low, high)
        return value

    def _normalize(values):
        if isinstance(values, pd.Series):
            return list(values)
        if isinstance(values, (list, tuple)):
            return list(values)
        return [values]

    goals_list = _normalize(goals)
    penalties_list = _normalize(penalties)

    if not goals_list and not penalties_list:
        return pd.DataFrame(columns=["Team", "Match Result"])

    if len(goals_list) == 1 and len(penalties_list) > 1:
        goals_list = goals_list * len(penalties_list)
    elif len(penalties_list) == 1 and len(goals_list) > 1:
        penalties_list = penalties_list * len(goals_list)
    elif len(goals_list) != len(penalties_list):
        raise ValueError("goals and penalties must have the same length or be broadcastable.")

    rows = []
    for idx, (g_raw, p_raw) in enumerate(zip(goals_list, penalties_list), start=1):
        g = _resolve(g_raw)
        p = _resolve(p_raw)

        if not isinstance(g, int):
            g = int(g)
        if not isinstance(p, int):
            p = int(p)

        fine = p * PENALTY_COST
        match_result = f"Goals: {g}, Penalties: {p}, Fine: {fine}"
        rows.append({"Team": f"Team {idx}", "Match Result": match_result})

    return pd.DataFrame(rows, columns=["Team", "Match Result"])
