    if rng_seed is not None:
        seed(rng_seed)

    def _as_list(value):
        if isinstance(value, (str, bytes)):
            raise TypeError("goals and penalties must be numeric values or sequences of numeric values")
        try:
            return list(value), True
        except TypeError:
            return [value], False

    goals_list, goals_is_iter = _as_list(goals)
    penalties_list, penalties_is_iter = _as_list(penalties)

    if len(goals_list) == 0 and len(penalties_list) == 0:
        return pd.DataFrame(columns=["Team", "Match Result"])

    if goals_is_iter and penalties_is_iter and len(goals_list) != len(penalties_list):
        raise ValueError("goals and penalties must have the same length")

    if goals_is_iter and not penalties_is_iter:
        penalties_list = penalties_list * len(goals_list)
    elif penalties_is_iter and not goals_is_iter:
        goals_list = goals_list * len(penalties_list)

    def _validate(values, name):
        for value in values:
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{name} must contain integers")
            if value < 0:
                raise ValueError(f"{name} must be non-negative")

    _validate(goals_list, "goals")
    _validate(penalties_list, "penalties")

    FINE_COST = 100
    teams = [f"Team {i + 1}" for i in range(len(goals_list))]
    match_results = [
        f"Goals: {g}, Fine: {p * FINE_COST}"
        for g, p in zip(goals_list, penalties_list)
    ]

    return pd.DataFrame({"Team": teams, "Match Result": match_results})
