from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    """
    Extract regex matches from all regular files in a directory.

    For each file, the function returns a list of matches. If a match is a
    parenthesized substring like "(abc)", the returned value is "abc"
    (the content between the parentheses).
    """
    base_dir = Path(directory_path)
    if not base_dir.is_dir():
        return {}

    pattern = re.compile(regex_pattern)
    results = {}

    for file_path_str in sorted(glob.glob(str(base_dir / "*"))):
        file_path = Path(file_path_str)
        if not file_path.is_file():
            continue

        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        matches = []
        for match in pattern.finditer(text):
            token = match.group(0)
            if len(token) >= 2 and token.startswith("(") and token.endswith(")"):
                matches.append(token[1:-1])
            else:
                matches.append(token)

        results[file_path.name] = matches

    return results
